+package compiler.stringopts;
+
+public class TestStringConcatAppendUncommonTrap {
+
+    public static void main (String... args) {
+        for (int i = 0; i < 10000; i++) {
+            String s = f(" ");
+            if (!s.equals("    ")) {
+                throw new RuntimeException("wrong result.");
+            }
+            String z = g(new StringBuilder(" "));
